# SPDX-License-Identifier: MIT
<# .SYNOPSIS Performs read-only review inspection and records command exit evidence. #>
[CmdletBinding()]
param(
    [Parameter(Mandatory)][ValidateSet('Read','MarkerInstructions','Identity','Native')][string]$Task,
    [string]$Path,
    [int]$Start = 1,
    [int]$Count = 180,
    [ValidateSet('rg','git','gh','codex','claude','cline','grok')][string]$CommandName,
    [string[]]$Arguments
)
$ErrorActionPreference = 'Stop'
$receiptRoot = $PSScriptRoot
$exitCode = 0
switch ($Task) {
    'Read' {
        if ($Path -match 'AGENTS-README-FIRST|TODO\.yaml|\.creds|current-turn|session-state') { throw 'Use the authorized specialized reader for this source.' }
        $lines = [IO.File]::ReadAllLines($Path)
        Write-Output "SOURCE $Path totalLines=$($lines.Count)"
        for ($index = $Start - 1; $index -lt [Math]::Min($lines.Count, $Start + $Count - 1); $index++) {
            Write-Output ('{0}: {1}' -f ($index + 1), $lines[$index])
        }
    }
    'MarkerInstructions' {
        Import-Module powershell-yaml
        $marker = ConvertFrom-Yaml ([IO.File]::ReadAllText('/home/sharpninja/github/McpServer/AGENTS-README-FIRST.yaml'))
        $instructions = [string]$marker.prompt
        foreach ($keyName in @('apiKey','signature')) {
            $secretValue = [string]$marker[$keyName]
            if ($secretValue) { $instructions = $instructions.Replace($secretValue,'[REDACTED:api-key]') }
        }
        $lines = $instructions -split "`n"
        Write-Output "RUNTIME INSTRUCTIONS totalLines=$($lines.Count); connection fields withheld"
        for ($index = $Start - 1; $index -lt [Math]::Min($lines.Count, $Start + $Count - 1); $index++) { Write-Output ('{0}: {1}' -f ($index + 1),$lines[$index]) }
    }
    'Identity' {
        $rolloutFile = Get-ChildItem -LiteralPath '/home/sharpninja/.codex/sessions/2026/10/17' -File | Where-Object Name -Like "*$($env:CODEX_THREAD_ID).jsonl" | Select-Object -First 1
        if (-not $rolloutFile) { throw 'Own rollout not found.' }
        $lineNumber = 0
        foreach ($line in [IO.File]::ReadLines($rolloutFile.FullName)) {
            $lineNumber++
            if ($line -notmatch '"type":"(?:turn_context|session_meta)"') { continue }
            $entry = ConvertFrom-Json $line
            $proof = [ordered]@{ RolloutPath = $rolloutFile.FullName; Line = $lineNumber; Type = $entry.type; TimestampUtc = $entry.timestamp; ThreadId = $env:CODEX_THREAD_ID; Model = $entry.payload.model; Effort = $entry.payload.effort; SessionId = $entry.payload.id; CliVersion = $entry.payload.cli_version; Cwd = $entry.payload.cwd }
            $proof | ConvertTo-Json -Depth 10
            if ($entry.type -eq 'turn_context') { $proof | ConvertTo-Json -Depth 10 | Set-Content -LiteralPath (Join-Path $receiptRoot 'hv-r1-identity.json') }
        }
    }
    'Native' {
        & $CommandName @Arguments
        $exitCode = $LASTEXITCODE
    }
}
$commandReceipt = [ordered]@{ TimestampUtc = [DateTime]::UtcNow.ToString('o'); TimestampLocal = (Get-Date).ToString('s'); Task = $Task; Path = $Path; Start = $Start; Count = $Count; Command = $CommandName; Arguments = $Arguments; ExitCode = $exitCode }
$commandReceipt | ConvertTo-Json -Depth 10 -Compress | Add-Content -LiteralPath (Join-Path $receiptRoot 'hv-r1-commands.jsonl')
Write-Output "EXIT_CODE=$exitCode"
exit $exitCode

