320: function Invoke-McpFailsafeLegacyQueueMigration {
321:     <#
322:     .SYNOPSIS
323:         Copy-then-delete legacy plugin failsafe YAML into the V4 pending directory after SHA-256 match.
324:     #>
325:     [CmdletBinding()]
326:     param(
327:         [Parameter(Mandatory)][string]$WorkspacePath,
328:         [Parameter(Mandatory)][string]$PendingDir
329:     )
330: 
331:     $mcpRoot = Join-Path $WorkspacePath '.mcpServer'
332:     if (-not (Test-Path -LiteralPath $mcpRoot -PathType Container)) {
333:         return
334:     }
335: 
336:     [void][System.IO.Directory]::CreateDirectory($PendingDir)
337: 
338:     $legacyDirs = New-Object System.Collections.Generic.List[string]
339:     foreach ($child in [System.IO.Directory]::GetDirectories($mcpRoot)) {
340:         $name = [System.IO.Path]::GetFileName($child)
341:         if ([string]::Equals($name, 'failsafe', [System.StringComparison]::OrdinalIgnoreCase)) {
342:             continue
343:         }
344: 
345:         $legacy = Join-Path $child 'failsafe'
346:         if (Test-Path -LiteralPath $legacy -PathType Container) {
347:             $legacyDirs.Add($legacy)
348:         }
349:     }
350: 
351:     foreach ($legacy in $legacyDirs) {
352:         $files = @(Get-ChildItem -LiteralPath $legacy -File -Filter '*.yaml' -ErrorAction SilentlyContinue)
353:         foreach ($file in $files) {
354:             $dest = Join-Path $PendingDir $file.Name
355:             if (-not (Test-Path -LiteralPath $dest)) {
356:                 Copy-Item -LiteralPath $file.FullName -Destination $dest -Force
357:             }
358: 
359:             if (Test-Path -LiteralPath $dest) {
360:                 $sourceHash = Get-McpFailsafeFileSha256Hex -Path $file.FullName
361:                 $destHash = Get-McpFailsafeFileSha256Hex -Path $dest
362:                 if ($sourceHash -eq $destHash) {
363:                     Remove-Item -LiteralPath $file.FullName -Force
364:                 }
365:             }
366:         }
367:     }
368: }
