// @exec: {"max_output_tokens": 12000}
const results=await Promise.allSettled([
tools.exec_command({cmd:"pwsh.exe -NoProfile -NonInteractive -File './docs/receipts/hv/hv-r1-inspect.ps1' -Task Read -Path './docs/architecture/SessionTurn-Review-AgentContext-Architecture-Amendment-1-Durable-HV.md' -Start 2584 -Count 230",shell:"pwsh.exe",login:false,max_output_tokens:5000}),
tools.exec_command({cmd:"pwsh.exe -NoProfile -NonInteractive -File './docs/receipts/hv/hv-r1-source-checks.ps1' -Task Cline",shell:"pwsh.exe",login:false,max_output_tokens:6500}),
tools.exec_command({cmd:"pwsh.exe -NoProfile -NonInteractive -File './docs/receipts/hv/hv-r1-source-checks.ps1' -Task ProbeInventory",shell:"pwsh.exe",login:false,max_output_tokens:5500})
]);for(let i=0;i<results.length;i++){text(i);if(results[i].status==="fulfilled")text(results[i].value.output);else text(results[i]);}
text(await tools.write_stdin({session_id:67673,chars:"",yield_time_ms:1000,max_output_tokens:5500}));

