+# SPDX-License-Identifier: Apache-2.0
+<# .SYNOPSIS Performs independent read-only comparisons and captures primary-source evidence. #>
+[CmdletBinding(SupportsShouldProcess)]
+param([Parameter(Mandatory)][ValidateSet('Requirements','Cli','GitHub','Static')][string]$Task)
+$ErrorActionPreference = 'Stop'
+if (-not $PSCmdlet.ShouldProcess('Reviewer receipt files only', $Task)) { return }
+$docPath = './docs/architecture/SessionTurn-Review-AgentContext-Architecture-Amendment-1-Durable-HV.md'
+$doc = [IO.File]::ReadAllText($docPath)
+$commands = [Collections.Generic.List[object]]::new()
+function Invoke-CapturedNative {
+    <# .SYNOPSIS Captures one read-only native command without echoing its full result. #>
+    param([string]$Program, [string[]]$ArgumentList, [string]$Name)
+    $result = @(& $Program @ArgumentList 2>&1 | ForEach-Object { $_.ToString() })
+    $code = $LASTEXITCODE
+    $result | Set-Content -LiteralPath (Join-Path $PSScriptRoot "hv-r1-$Name.txt")
+    $record = [ordered]@{ TimestampUtc = [DateTime]::UtcNow.ToString('o'); Command = $Program; Arguments = $ArgumentList; ExitCode = $code; Receipt = "hv-r1-$Name.txt"; Lines = $result.Count }
+    $commands.Add($record)
+    $record | ConvertTo-Json -Compress
+}
+switch ($Task) {
+    'Cli' {
+        foreach ($cli in @('codex','claude','cline','grok','copilot')) {
+            Invoke-CapturedNative -Program $cli -ArgumentList @('--version') -Name "$cli-version"
+            Invoke-CapturedNative -Program $cli -ArgumentList @('--help') -Name "$cli-help"
+        }
+    }
+    'GitHub' {
+        Invoke-CapturedNative -Program gh -ArgumentList @('pr','view','81','--json','number,title,url,mergedAt,mergeCommit,headRefOid,reviews,comments') -Name 'pr81'
+        Invoke-CapturedNative -Program gh -ArgumentList @('api','repos/sharpninja/McpServer/pulls/81/comments','--paginate') -Name 'pr81-review-comments'
+        Invoke-CapturedNative -Program gh -ArgumentList @('api','repos/sharpninja/McpServer/pulls/81/reviews','--paginate') -Name 'pr81-reviews'
+        Invoke-CapturedNative -Program git -ArgumentList @('ls-remote','origin','refs/heads/docs/hv-architecture-amendment-20261016') -Name 'remote-head'
+        Invoke-CapturedNative -Program git -ArgumentList @('reflog','show','--date=iso','refs/remotes/origin/docs/hv-architecture-amendment-20261016') -Name 'push-reflog'
+        Invoke-CapturedNative -Program git -ArgumentList @('log','--format=%H %P','36783b79..d3a0beb10b0879f20fb307f205a3bff25ac3a441') -Name 'ancestry'
+    }
+    'Requirements' {
+        $records = Get-Content -LiteralPath (Join-Path $PSScriptRoot 'hv-r1-requirements-selected.json') -Raw | ConvertFrom-Json -Depth 80
+        $maps = Get-Content -LiteralPath (Join-Path $PSScriptRoot 'hv-r1-mappings-selected.json') -Raw | ConvertFrom-Json -Depth 80
+        $catalog = [regex]::Matches($doc, '(?ms)^- (FR-MCP-HVPIPE-(\d{3})) (.+?)\. Sources (.+?)\. (UC-HV-[^.]+)\. TR(?:-MCP-HVPIPE-\d{3})?: (.+?)\.\r?\n(.*?)(?=^- FR-MCP-HVPIPE-|^### 19\.2)')
+        $differences = [Collections.Generic.List[object]]::new()
+        $counts = @()
+        foreach ($entry in $catalog) {
+            $frId = $entry.Groups[1].Value; $suffix = $entry.Groups[2].Value; $title = $entry.Groups[3].Value
+            $sources = $entry.Groups[4].Value; $useCases = $entry.Groups[5].Value; $contract = $entry.Groups[6].Value
+            $acs = @([regex]::Matches($entry.Groups[7].Value, '(?m)^  - (AC\d{3}) (.+)\r?$') | ForEach-Object { [ordered]@{ id = $_.Groups[1].Value; text = $_.Groups[2].Value.TrimEnd("`r") } })
+            $fr = @($records | Where-Object id -EQ $frId)[0]
+            $tr = @($records | Where-Object id -EQ "TR-MCP-HVPIPE-$suffix")[0]
+            $test = @($records | Where-Object id -EQ "TEST-MCP-HVPIPE-$suffix")[0]
+            $checks = @(
+                @{ Field = 'FR.title'; Actual = $fr.title; Expected = $title },
+                @{ Field = 'FR.description'; Actual = $fr.description; Expected = "$title. Sources: $sources. Use cases: $useCases." },
+                @{ Field = 'TR.title'; Actual = $tr.title; Expected = "${title}: implementation contract" },
+                @{ Field = 'TR.description'; Actual = $tr.description; Expected = "Implementation contract of ${frId}: $contract. Each named unit, policy, process, component, and entity is specified in docs/architecture/SessionTurn-Review-AgentContext-Architecture-Amendment-1-Durable-HV.md (sections 10 to 16)." },
+                @{ Field = 'TR.AC001'; Actual = $tr.acceptanceCriteria[0].text; Expected = "The units, policies, processes, components, and entities named in this contract satisfy every acceptance criterion of $frId ($($acs.Count) criteria), proven by TEST-MCP-HVPIPE-$suffix." },
+                @{ Field = 'TEST.title'; Actual = $test.title; Expected = "${title}: named tests" }
+            )
+            $testNames = @()
+            foreach ($ac in $acs) {
+                $checks += @{ Field = "FR.$($ac.id)"; Actual = @($fr.acceptanceCriteria | Where-Object id -EQ $ac.id)[0].text; Expected = $ac.text }
+                $lastParenthesis = [regex]::Match($ac.text, '\(([^()]*)\)\.\s*$').Groups[1].Value
+                $names = @([regex]::Matches($lastParenthesis, '`([^`]+)`') | ForEach-Object { $_.Groups[1].Value })
+                if (-not $names.Count) { $differences.Add(@{ Id = $frId; Field = $ac.id; Defect = 'No test name parsed from final parenthesis'; Text = $ac.text }) }
+                $testNames += $names
+                $checks += @{ Field = "TEST.$($ac.id)"; Actual = @($test.acceptanceCriteria | Where-Object id -EQ $ac.id)[0].text; Expected = "Named tests exist and prove ${frId}-$($ac.id): $($names -join ', ')." }
+            }
+            $checks += @{ Field = 'TEST.description'; Actual = $test.description; Expected = "Named tests of ${frId}: $($testNames -join '; ')." }
+            foreach ($check in $checks) { if ($check.Actual -cne $check.Expected) { $differences.Add(@{ Id = $frId; Field = $check.Field; Actual = $check.Actual; Expected = $check.Expected }) } }
+            $edges = @($maps | Where-Object frId -EQ $frId)
+            if ($edges.Count -ne 2 -or @($edges | Where-Object trId -EQ $tr.id).Count -ne 1 -or @($edges | Where-Object testId -EQ $test.id).Count -ne 1) { $differences.Add(@{ Id = $frId; Field = 'mappings'; Actual = $edges }) }
+            $counts += [ordered]@{ Id = $frId; DocumentAcCount = $acs.Count; StoreFrAcCount = @($fr.acceptanceCriteria).Count; StoreTrAcCount = @($tr.acceptanceCriteria).Count; StoreTestAcCount = @($test.acceptanceCriteria).Count; TestNames = $testNames; Mappings = $edges.Count; Pending = ($fr.status -eq 'pending' -and $tr.status -eq 'pending' -and $test.status -eq 'pending') }
+        }
+        $report = [ordered]@{ TimestampUtc = [DateTime]::UtcNow.ToString('o'); CatalogCount = $catalog.Count; RecordCount = $records.Count; AcCount = ($counts.DocumentAcCount | Measure-Object -Sum).Sum; MappingEdges = $maps.Count; Differences = @($differences.ToArray()); Counts = $counts }
+        $report | ConvertTo-Json -Depth 40 | Set-Content -LiteralPath (Join-Path $PSScriptRoot 'hv-r1-requirement-comparison.json')
+        $report | Select-Object TimestampUtc,CatalogCount,RecordCount,AcCount,MappingEdges,Differences | ConvertTo-Json -Depth 20
+    }
+    'Static' {
+        $report = [ordered]@{ TimestampUtc = [DateTime]::UtcNow.ToString('o'); MermaidCount = ([regex]::Matches($doc, '(?m)^```mermaid')).Count; ActivityCount = ([regex]::Matches($doc, '(?m)^flowchart ')).Count; SequenceCount = ([regex]::Matches($doc, '(?m)^sequenceDiagram')).Count; EnOrEmDashes = ([regex]::Matches($doc, '[\u2013\u2014]')).Count; TableRows = ([regex]::Matches($doc, '(?m)^\s*\|')).Count; Spdx = $doc.StartsWith('<!-- SPDX-License-Identifier: Apache-2.0 -->'); FoundationHash = (Get-FileHash -LiteralPath './docs/architecture/SessionTurn-Review-AgentContext-Architecture.md' -Algorithm SHA256).Hash }
+        $report | ConvertTo-Json | Set-Content -LiteralPath (Join-Path $PSScriptRoot 'hv-r1-static.json')
+        $report | ConvertTo-Json
+    }
+}
+foreach ($command in $commands) { $command | ConvertTo-Json -Depth 10 -Compress | Add-Content -LiteralPath (Join-Path $PSScriptRoot 'hv-r1-commands.jsonl') }
+[ordered]@{ TimestampUtc = [DateTime]::UtcNow.ToString('o'); Command = 'hv-r1-verify.ps1'; Task = $Task; ExitCode = 0 } | ConvertTo-Json -Compress | Add-Content -LiteralPath (Join-Path $PSScriptRoot 'hv-r1-commands.jsonl')
*** End Patch"));
