9: /// <c>OwnerWorkspaceId</c> and entity <c>WorkspacePath</c> column) are stored in the lexical canonical
10: /// form from <see cref="WorkspaceIdentity.CanonicalizeWorkspaceId"/>. The converter applies on writes
11: /// and, on relational providers, to query parameters compared with these properties, so a predicate
12: /// built from a caller's raw path (<c>Q:\ws</c>) matches the stored canonical row (<c>Q:/ws</c>). The
13: /// comparer makes the change tracker treat both spellings as one key.
14: /// </summary>
15: internal static class WorkspaceKeyConversion
16: {
17:     private static readonly HashSet<string> PropertyNames = new(StringComparer.Ordinal)
18:     {
19:         "WorkspaceId",
20:         "OwnerWorkspaceId",
21:         "WorkspacePath",
22:     };
23: 
24:     private static readonly ValueConverter<string, string> Converter = new(
25:         value => WorkspaceIdentity.CanonicalizeWorkspaceId(value),
26:         value => value);
27: 
28:     private static readonly ValueComparer<string> Comparer = new(
29:         (left, right) => left == null
30:             ? right == null
31:             : right != null && WorkspaceIdentity.CanonicalizeWorkspaceId(left) == WorkspaceIdentity.CanonicalizeWorkspaceId(right),
32:         value => value == null ? 0 : WorkspaceIdentity.CanonicalizeWorkspaceId(value).GetHashCode(StringComparison.Ordinal),
33:         value => value);
34: 
35:     /// <summary>Applies the canonical converter and comparer to every workspace-key property in the model.</summary>
36:     internal static void Apply(ModelBuilder modelBuilder)
37:     {
38:         foreach (var entityType in modelBuilder.Model.GetEntityTypes())
39:         {
40:             foreach (var property in entityType.GetDeclaredProperties())
41:             {
42:                 if (property.ClrType != typeof(string) || !PropertyNames.Contains(property.Name))
43:                     continue;
44: 
45:                 property.SetValueConverter(Converter);
46:                 property.SetValueComparer(Comparer);
47:             }
48:         }
49:     }
